function count(W,H,fleet){
  // fleet: array of lengths, descending. Canonical: identical lengths placed in increasing anchor index.
  const N=W*H;
  const occ=new Uint8Array(N);
  const blocked=new Uint8Array(N);
  // precompute placements: list of {cells:[], halo:[]}
  const places=[];
  for(let L=1;L<=Math.max(...fleet);L++){
    const arr=[];
    for(let y=0;y<H;y++)for(let x=0;x<W;x++){
      for(const [dx,dy] of (L===1?[[1,0]]:[[1,0],[0,1]])){
        const cells=[];let ok=true;
        for(let i=0;i<L;i++){const cx=x+dx*i,cy=y+dy*i;if(cx>=W||cy>=H){ok=false;break;}cells.push(cy*W+cx);}
        if(!ok)continue;
        const halo=new Set();
        for(const c of cells){const cy=(c/W)|0,cx=c%W;
          for(let ay=cy-1;ay<=cy+1;ay++)for(let ax=cx-1;ax<=cx+1;ax++){if(ax<0||ay<0||ax>=W||ay>=H)continue;halo.add(ay*W+ax);}}
        arr.push({cells,halo:[...halo]});
      }
    }
    places[L]=arr;
  }
  let total=0;
  function rec(i,minIdx){
    if(i===fleet.length){total++;return;}
    const L=fleet[i];
    const arr=places[L];
    const start=(i>0&&fleet[i-1]===L)?minIdx:0;
    for(let p=start;p<arr.length;p++){
      const pl=arr[p];
      let ok=true;
      for(const c of pl.cells){if(blocked[c]){ok=false;break;}}
      if(!ok)continue;
      const added=[];
      for(const c of pl.halo){if(!blocked[c]){blocked[c]=1;added.push(c);}}
      rec(i+1,p+1);
      for(const c of added)blocked[c]=0;
    }
  }
  rec(0,0);
  return total;
}
