function marg(){const p=new Float64Array(N);for(let k=0;k<sz;k++){const i=S[k];for(let c=0;c<N;c++)if(occ(i,c))p[c]++;}for(let c=0;c<N;c++)p[c]/=sz;return p;}
const shots=[];
function plain(){const p=marg();let best=-1,bp=-1;for(let c=0;c<N;c++){if(shots.includes(c))continue;if(p[c]>bp){bp=p[c];best=c;}}
 let any=false;for(let k=0;k<sz;k++)if(!occ(S[k],best)){any=true;break;}const a=any?0:1;const out=new Int32Array(sz);let m=0;for(let k=0;k<sz;k++)if(occ(S[k],best)===a)out[m++]=S[k];S=out.subarray(0,m);sz=m;shots.push(best);return a;}
