 const sBits=Math.log2(sz/n2);
 const better=(zBits>sBits+1e-9||zHits>sHits)?"ДА":"нет";
 console.log(`${String(t+1).padStart(3)} | ${String(sz).padStart(7)} | ${zBits.toFixed(2)} / ${zHits} | ${sBits.toFixed(2)} / ${sHits} | ${better}`);
